window.HOEREN_TESTS[39] = {"id":"sommer-und-strand","name":"Sommer und Strand","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Lisa, hier ist Anna. Also, wir möchten dieses Jahr im Sommer zum Strand fahren, aber wohin? Italien wäre nett, oder Spanien. Eigentlich wollten wir nach Griechenland, aber das ist zu weit. Was meinst du? Italien klingt am besten, Spanien ist uns zu voll. Ruf mich zurück.","gender":"f","q":"Wohin fährt die Familie?","opts":["Italien.","Spanien.","Griechenland."],"correct":0},{"transcript":"Achtung Strand-Besucher: Die Wassertemperatur ist heute 22 Grad, angenehm warm. Das heißt nicht, dass das Wasser nur warm ist. Die rote Flagge bedeutet: Schwimmen gefährlich, weil die Strömung stark ist. Der Strand ist nicht geschlossen. Nur erfahrene Schwimmer ins Wasser. Kinder bitte immer mit Erwachsenen.","gender":"m","q":"Was bedeutet die rote Flagge?","opts":["Wasser ist warm.","Schwimmen gefährlich.","Strand geschlossen."],"correct":1},{"transcript":"Hi Tom, hier ist Markus. Ich habe Sonnenstich vom Strand bekommen, bin total müde, Kopfschmerzen, kann nicht raus. Keine Erkältung und keine Bauchschmerzen, wirklich Sonnenstich. Wir können nicht heute Abend ins Restaurant. Verschieben wir auf morgen? Heute brauche ich nur Bett und Schatten, sorry Tom.","gender":"m","q":"Was hat Markus?","opts":["Sonnenstich.","Erkältung.","Bauchschmerzen."],"correct":0},{"transcript":"Liebe Strand-Gäste: Heute Abend findet eine Beach-Party statt, Live-Musik, Cocktails, Tanz unter den Sternen. Eintritt für Erwachsene 15 Euro, nicht kostenlos und nicht 20 Euro, ab 20 Uhr. Kinder bis 14 Jahre kostenlos, aber bitte nur bis 22 Uhr. Wir freuen uns auf einen schönen Abend am Strand!","gender":"f","q":"Was kostet der Eintritt für Erwachsene?","opts":["Kostenlos.","15 Euro.","20 Euro."],"correct":1},{"transcript":"Hi Lisa, hier ist Sara. Ich habe meinen Bikini vergessen, kannst du mir einen leihen? Wir gehen ja heute Mittag zum Strand. Wenn du keinen hast, muss ich einen Bikini kaufen. Im Hotelshop kosten sie 50 Euro, viel zu teuer. Ruf mich an.","gender":"f","q":"Was möchte Sara?","opts":["Schwimmen gehen.","Einen Bikini kaufen.","Einen Bikini leihen."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was machen sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Strand ist diese Woche endlich warm genug."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Dann planen wir für jeden Tag etwas anderes."},{"speaker":"Lukas","gender":"m","text":"Surfen ist montags dran. Die Wellen sind früh noch hoch."},{"speaker":"Lisa","gender":"f","text":"Dafür stehst du sehr früh auf. Ich brauche einen Tag mehr."},{"speaker":"Lukas","gender":"m","text":"Nehmen wir das Kajak auch mit an den Strand?"},{"speaker":"Lisa","gender":"f","text":"Nein. Wir nehmen kein Kajak mit."},{"speaker":"Lukas","gender":"m","text":"Du bist einen Tag später mit dem Lehrer dran."},{"speaker":"Lisa","gender":"f","text":"Ich fahre am Dienstag Wasserski. Er wartet unten am Steg."},{"speaker":"Lukas","gender":"m","text":"Es wird am Mittwoch heiß und der Wind bleibt schwach."},{"speaker":"Lisa","gender":"f","text":"Wir machen Sonnenbaden und lesen. Ein dickes Buch liegt schon in der Tasche."},{"speaker":"Lukas","gender":"m","text":"Die Kinder sind am Donnerstag den ganzen Tag am Wasser."},{"speaker":"Lisa","gender":"f","text":"Sie bauen Sandburgen. Der Eimer steht schon im Kofferraum."},{"speaker":"Lukas","gender":"m","text":"Wollen wir an einem Tag auch segeln?"},{"speaker":"Lisa","gender":"f","text":"Nein. Segeln machen wir auch nicht."},{"speaker":"Lukas","gender":"m","text":"Ein paar Leute wollen am Freitag unter die Oberfläche."},{"speaker":"Lisa","gender":"f","text":"Tauchen steht an. Die Brillen liegen schon bereit."},{"speaker":"Lukas","gender":"m","text":"Ich schreibe die Tage an die Kühlschranktür."},{"speaker":"Lisa","gender":"f","text":"Morgens sehen wir dann sofort den Plan."}],"options":[{"letter":"a","text":"Kajak fahren"},{"letter":"b","text":"Wasserski fahren"},{"letter":"c","text":"Schnorcheln"},{"letter":"d","text":"Sandburgen bauen"},{"letter":"e","text":"Segeln"},{"letter":"f","text":"Tauchen"},{"letter":"g","text":"Beach-Volleyball"},{"letter":"h","text":"Sonnenbaden und lesen"},{"letter":"i","text":"Surfen"}],"items":[{"person":"Montag","correct":"i"},{"person":"Dienstag","correct":"b"},{"person":"Mittwoch","correct":"h"},{"person":"Donnerstag","correct":"d"},{"person":"Freitag","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Wo finde ich Sonnencreme? Ich brauche LSF 30, LSF 50 oder reicht LSF 20?"},{"speaker":"Verkäuferin","gender":"f","text":"Im hinteren Bereich des Shops. Wir haben verschiedene Stärken, 20, 30 und 50."},{"speaker":"Kundin","gender":"f","text":"Welche für ein 4-jähriges Kind? LSF 20 ist mir zu wenig, oder?"},{"speaker":"Verkäuferin","gender":"f","text":"Mindestens LSF 50, kinderhaut braucht den höchsten Schutz. LSF 30 ist für Erwachsene okay, LSF 20 nicht für Kinder."},{"speaker":"Kundin","gender":"f","text":"Dann LSF 50 bitte, eine große Tube."}],"q":"Welche Stärke empfiehlt sie?","opts":["LSF 30.","LSF 50.","LSF 20."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Wann ist die beste Zeit am Strand? Morgens, mittags oder abends?"},{"speaker":"Mutter","gender":"f","text":"Morgens vor 11 oder abends nach 16 Uhr. Mittags lieber nicht."},{"speaker":"Vater","gender":"m","text":"Mittags zu heiß? Die Kinder wollen aber mittags ins Wasser."},{"speaker":"Mutter","gender":"f","text":"Genau, von 12 bis 15 Uhr ist es gefährlich für die Haut. Morgens und abends ist besser, mittags Schatten."},{"speaker":"Vater","gender":"m","text":"Okay, dann gehen wir morgens und abends. Mittags bleiben wir im Hotel."}],"q":"Wann sollte man nicht am Strand sein?","opts":["Morgens.","Mittags.","Abends."],"correct":1},{"lines":[{"speaker":"Tom","gender":"m","text":"Lisa, wo bist du? Ich finde dich nicht am Strand! Bist du im Wasser oder unter einem Schirm?"},{"speaker":"Lisa","gender":"f","text":"Bin im Schatten unter dem grünen Sonnenschirm, nicht im Wasser."},{"speaker":"Tom","gender":"m","text":"Ich sehe nur blaue Schirme. Unter dem blauen Schirm bist du nicht?"},{"speaker":"Lisa","gender":"f","text":"Nein, nicht unter dem blauen Schirm und nicht im Wasser. Geh näher zum Restaurant, da ist der grüne."},{"speaker":"Tom","gender":"m","text":"Okay, ich komme zum grünen Schirm. Bleib dort bitte."}],"q":"Wo ist Lisa?","opts":["Unter dem grünen Schirm.","Unter dem blauen Schirm.","Im Wasser."],"correct":0},{"lines":[{"speaker":"Junge","gender":"m","text":"Mama, ich möchte Eis, schokolade, Erdbeere oder Vanille?"},{"speaker":"Mutter","gender":"f","text":"Welches möchtest du wirklich? Schokolade haben sie vielleicht nicht."},{"speaker":"Junge","gender":"m","text":"Schokolade, oder Erdbeere, wenn Schokolade alle ist."},{"speaker":"Mutter","gender":"f","text":"Schokolade haben sie nicht heute. Erdbeere oder Vanille, was dann?"},{"speaker":"Junge","gender":"m","text":"Dann Vanille, erdbeere mag ich heute nicht so."},{"speaker":"Mutter","gender":"f","text":"Gut, eine Kugel Vanille, wir setzen uns in den Schatten."}],"q":"Welches Eis bekommt der Junge?","opts":["Vanille.","Erdbeere.","Schokolade."],"correct":0},{"lines":[{"speaker":"Tourist","gender":"m","text":"Wie viel kostet eine Strand-Liege? 10 Euro, 15 Euro, oder nichts, ist sie frei?"},{"speaker":"Vermieter","gender":"m","text":"Eine Liege 10 Euro pro Tag. Mit Schirm 15 Euro, nichts zahlen geht nicht, die Liegen sind nicht frei."},{"speaker":"Tourist","gender":"m","text":"Nur die Liege, kein Schirm. Also nicht 15 Euro."},{"speaker":"Vermieter","gender":"m","text":"Gerne, 10 Euro, nichts wäre schön, aber wir müssen die Liegen pflegen."},{"speaker":"Tourist","gender":"m","text":"Okay, 10 Euro, ich bleibe bis zum Abend."}],"q":"Was zahlt der Tourist?","opts":["Nichts.","15 Euro.","10 Euro."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Sandberg, einer Strand-Rettungsschwimmerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Sandberg, Sie arbeiten als Rettungsschwimmerin seit 10 Sommern. Wie sind Sie dazu gekommen?"},{"speaker":"Sandberg","gender":"f","text":"Ich liebe das Meer, schwimme seit meiner Kindheit. Mit 18 habe ich die Ausbildung gemacht — Erste Hilfe, Rettungsschwimmen, alles. Jetzt bin ich Teamleiterin am Strand von Rügen. Im Winter arbeite ich als Sportlehrerin."},{"speaker":"Reporter","gender":"m","text":"Wie oft müssen Sie jemanden retten?"},{"speaker":"Sandberg","gender":"f","text":"Echte Rettungen — etwa 10 pro Saison. Aber kleine Hilfen viel öfter: Kinder, die verloren sind, Quallen-Stiche, Sonnenstich. Pro Tag etwa fünf Vorfälle."},{"speaker":"Reporter","gender":"m","text":"Was sind die häufigsten Probleme?"},{"speaker":"Sandberg","gender":"f","text":"Eltern, die nicht aufpassen. Kinder schwimmen zu weit, die Eltern sehen es nicht. Auch ältere Leute, die mit Herzproblemen ins Meer gehen — gefährlich. Und Alkohol! Niemals trinken vor dem Schwimmen!"},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Besuchern?"},{"speaker":"Sandberg","gender":"f","text":"Auf die Flaggen achten — grün okay, gelb vorsichtig, rot nicht ins Wasser. Niemals allein ins Meer. Kinder immer im Blick haben. Sonnencreme! Wasser trinken — Dehydrierung passiert schnell."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie privat?"},{"speaker":"Sandberg","gender":"f","text":"Auch viel Sport. Aber im Urlaub fahre ich in die Berge — Berge, kein Meer! Sonst wäre es kein echter Urlaub für mich."}],"items":[{"q":"Frau Sandberg arbeitet im Winter als Lehrerin.","correct":"ja"},{"q":"Sie macht etwa 50 echte Rettungen pro Saison.","correct":"nein"},{"q":"Alkohol vor dem Schwimmen ist ein Problem.","correct":"ja"},{"q":"Die rote Flagge bedeutet, dass man vorsichtig schwimmen darf.","correct":"nein"},{"q":"Im Urlaub fährt sie ans Meer.","correct":"nein"}]}]};
